with parsed as (select id, plan, effective_from, discounts, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, element_at(tier_prices, 1) as entry_price from price_tiers where plan in ('enterprise', 'basic', 'pro')) select date_trunc('month', effective_from) as activity_month, case when entry_price >= 24 then 'LARGE' else 'SMALL' end as entry_price_tier, count(*) filter (where plan = 'pro') as pro_rows, count(distinct plan) as distinct_plans, avg(entry_price) filter (where plan = 'pro') as pro_avg_entry_price, avg(entry_price) as avg_entry_price, round(avg(entry_price), 2) as avg_entry_price_2, count(*) as cnt from parsed group by cube (date_trunc('month', effective_from), case when entry_price >= 24 then 'LARGE' else 'SMALL' end);
